python
def bookingRackFirstQualifyingSlip(drawers, k):
    a=drawers
    out=[]
    end=float('-inf')
    for s,e in sorted(a,key=lambda r:(r[1],r[0])):
        if s>=end:
            out.append(e-s)
            end=e
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int bookingRackFirstQualifyingSlip(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {int[][]rows=a.clone();Arrays.sort(rows,Comparator.comparingInt((int[]r)->r[1]).thenComparingInt(r->r[0]));int end=Integer.MIN_VALUE;for(int[]r:rows)if(r[0]>=end){out.add(r[1]-r[0]);end=r[1];}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
